const body = $json.body || {};
const docType = body.documentType;
const details = body.details;
const tone = body.tone || "Confident";
const yourName = (body.yourName || "").trim();
const yourRole = (body.yourRole || "").trim();

let who = "a professional";
if (yourName && yourRole) who = `${yourName}, ${yourRole}`;
else if (yourName) who = yourName;
else if (yourRole) who = `a ${yourRole}`;

// Style library — this is how you "teach" the model better writing habits.
// Edit any instructions/example below, or add a new document type as its own entry.
const library = {
  "Resume Bullet Points": {
    instructions: "You write resume bullet points. Each bullet starts with a strong action verb, includes a number or result where possible, and stays under 20 words. No buzzwords like 'synergy' or 'results-driven'. Write the way a confident professional would describe their own work to a colleague.",
    example: "Example style:\n- Rebuilt the company website, cutting page load time from 6s to 1.8s\n- Managed a product launch that brought in 200+ new customers in the first month"
  },
  "Resume Summary": {
    instructions: "You write a 3-4 line resume summary for the top of a resume. State years of experience, main skills, and one standout result. No clichés like 'hardworking team player' or 'passionate about excellence'.",
    example: "Example:\n\"Marketing coordinator with 6 years running social campaigns for retail brands. Known for turning small budgets into real results, including a campaign that grew one client's followers by 300% in four months.\""
  },
  "Cover Letter": {
    instructions: "You write cover letters that sound like a real person wrote them, not a template. Open with something specific about the role or company, not 'I am writing to apply for'. Keep it to 3 short paragraphs. End with a plain, confident closing line, not 'I look forward to hearing from you'.",
    example: "Example opening:\n\"Your job post mentions you need someone who can turn around slow customer response times. That's exactly the problem I solved in my last role, so I wanted to reach out directly.\""
  },
  "Professional Email": {
    instructions: "You write short, clear business emails. One idea per paragraph. No filler phrases like 'I hope this email finds you well' or 'Just circling back'. Get to the point in the first line.",
    example: "Example:\n\"Hi Sarah, following up on the invoice from last week. Can you confirm if payment has been sent? Thanks.\""
  },
  "Follow-Up Email": {
    instructions: "You write short follow-up emails after getting no response. Polite but direct, no guilt-tripping, one clear ask, easy to say yes to.",
    example: "Example:\n\"Hi John, checking in on the proposal I sent last Tuesday. Happy to answer any questions — is there a good day this week to talk?\""
  },
  "Meeting Agenda": {
    instructions: "You write meeting agendas. State the meeting goal in one line at the top, then list 3-6 topics with a time estimate for each. Note who should prepare what, if relevant.",
    example: "Example:\nGoal: Decide on Q2 marketing budget\n1. Review Q1 results (10 min)\n2. Budget options (15 min)\n3. Decision and next steps (10 min)"
  },
  "Meeting Minutes": {
    instructions: "You write meeting notes after a meeting. List attendees, key decisions, and action items with owner names and due dates. No long narrative, just facts.",
    example: "Example:\nDecisions: Approved the new logo design.\nAction items:\n- Sarah to send final files by Friday\n- Amir to update the website by Monday"
  },
  "Memo": {
    instructions: "You write internal memos. Use a short heading, a one-line summary at the top, then 2-4 short sections with clear headers. Plain, direct language, no corporate jargon.",
    example: "Example header:\nTo: Team\nFrom: Operations\nDate: [date]\nRe: Office closing schedule"
  },
  "Business Proposal": {
    instructions: "You write short business proposals for a client or partner. Structure: the problem, the proposed solution, what's included, cost, timeline. Be specific about deliverables, not vague marketing language.",
    example: "Example line:\n\"Problem: your checkout page takes 7 steps and loses customers. Solution: reduce it to 3 steps. Timeline: 2 weeks. Cost: $900.\""
  },
  "RFQ Response": {
    instructions: "You write RFQ (request for quotation) responses. Be specific about price, timeline, and what is included. No vague promises like 'best quality service'. Structure: short intro, pricing in plain text, timeline, next steps.",
    example: "Example line:\n\"Total cost: $450. Delivery: 7 business days. Includes 2 rounds of revisions.\""
  },
  "Freelance Proposal": {
    instructions: "You write Freelancer.com / Upwork style proposals. Open by referencing something specific from the job post, not 'I am a skilled developer'. Mention one relevant past project in one sentence. Keep it under 120 words. End with a direct question to start a conversation.",
    example: "Example opening:\n\"You mentioned your current site takes over 5 seconds to load on mobile — that's almost always a plugin or image problem, both fixable in a day or two.\""
  },
  "LinkedIn About Section": {
    instructions: "You write LinkedIn 'About' sections. First-person, conversational but professional, 3-4 short paragraphs. Start with what the person does and who they help, end with how to reach them. No 'passionate about' or 'thought leader'.",
    example: "Example opening:\n\"I help small businesses fix slow, confusing websites so more visitors actually become customers.\""
  },
  "Performance Review Feedback": {
    instructions: "You write performance review comments for an employee. Use specific examples, not vague praise. Balance one strength with one clear area to improve, written to encourage rather than discourage.",
    example: "Example:\n\"Handled the client migration project well, finishing two days early with no downtime. For next quarter, focus on documenting steps so the rest of the team can follow along without asking directly.\""
  },
  "Thank You Note": {
    instructions: "You write short thank-you notes for clients, colleagues, or after an interview. Be specific about what you're thanking them for, warm but not overly emotional, 3-5 sentences.",
    example: "Example:\n\"Thank you for taking the time to walk me through the role yesterday. I especially liked hearing about the new product launch, and I'm even more interested in joining the team now.\""
  },
  "Invoice Payment Reminder": {
    instructions: "You write payment reminder emails for unpaid invoices. Stay professional, state the invoice number and amount clearly, give a specific next step, and avoid sounding angry even on a second reminder.",
    example: "Example:\n\"Hi Maria, Invoice #204 for $600 was due on the 10th and I haven't received payment yet. Could you confirm when I can expect it?\""
  },
  "Project Status Update": {
    instructions: "You write short project status updates for clients or managers. Structure: what's done, what's in progress, what's blocked (if anything), what's next. Use short lines, not long paragraphs.",
    example: "Example:\nDone: Homepage redesign\nIn progress: Mobile menu fixes (50%)\nBlocked: Waiting on logo files from client\nNext: Checkout page testing"
  }
};

const chosen = library[docType] || library["Professional Email"];

const systemPrompt = `You are a professional business writer helping ${who} write clear, natural, human English for an international audience. Never use these words or phrases: delve, leverage, in today's fast-paced world, robust solution, cutting-edge, seamless, I hope this email finds you well, I look forward to hearing from you, as an AI. Vary sentence length. Sound confident, not robotic.\n\n${chosen.instructions}\n\n${chosen.example}\n\nTone requested: ${tone}`;

const userPrompt = `Write a ${docType} based on these details:\n\n${details}`;

// Replace with your own Ollama model name after importing (check with: ollama list)
return [{
  json: {
    model: "qwen2.5:3b",
    system: systemPrompt,
    prompt: userPrompt
  }
}];
